import{_ as i,l,o,c as s,v as d,p,x as n,d as t,i as E,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"商品期权与波动率","description":"","frontmatter":{"title":"商品期权与波动率","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-commodity-options.md","filePath":"quant/cn-commodity-options.md","lastUpdated":1789023840000}'),u={name:"quant/cn-commodity-options.md"};function m(A,a,c,B,f,V){const r=l("Mermaid");return o(),s("div",null,[a[1]||(a[1]=d('<h1 id="商品期权与波动率" tabindex="-1">商品期权与波动率 <a class="header-anchor" href="#商品期权与波动率" aria-label="Permalink to &quot;商品期权与波动率&quot;">​</a></h1><div class="epigraph"><p>商品期权长在期货上：标的是期货合约，时段含夜盘，涨跌停与保证金跟商品所走，波动率的季节性来自库存与天气，不是来自 T+1 股票。</p><footer>—— 上海期货交易所、大连商品交易所、郑州商品交易所期权合约与交易规则；对照[到期流程](/quant/options-expiration-process)与商品期货夜盘制度</footer></div><p><a href="/quant/cn-etf-options">上一课</a>停在权益 ETF 期权。本课的缺口是<strong>商品所期权</strong>：以商品期货为标的的期权，在大商所、郑商所、上期所（及能源中心等）上市。夜盘、交割月、持仓限额与期权到期必须联立。不把股票 LOB 的直觉搬来；商品微观结构另有开收盘与停板。后课转债回到交易所股票信用混合产品。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>权益波动率的状态变量是指数与 ETF；商品波动率的状态变量是库存、产季、便利收益与期货曲线形状。期权隐含波动沿期货曲线不同合约而变，近月可以因交割与逼仓预期而显著更高。问题是：商品量化若把「IV–RV」当权益 VRP 同一因子，会忽略季节与期限结构。回测必须按品种–合约月分段，而不是一个「商品期权」池。</p><p>制度：期权涨跌停、交易保证金、行权（多为美式或欧式以合约为准）、到期与期货交割月的关系，以各所合约表为准。股票 T+1 不适用。夜盘使信息在 A 股收盘后仍写入商品期货与期权，跨资产对冲有时钟差，见<a href="/quant/cn-night-session">夜盘</a>。</p><h3 id="做市、流动性与产业客户" tabindex="-1">做市、流动性与产业客户 <a class="header-anchor" href="#做市、流动性与产业客户" aria-label="Permalink to &quot;做市、流动性与产业客户&quot;">​</a></h3><p>商品期权流动性弱于主力期货，买卖价差宽，产业套保与专业做市占主导。CTA 与期权卖方在保证金上竞争同一现金。容量按期权市场深度与期货对冲可承受冲击估，不按商品现货市场规模估。</p><p><span class="marginnote">黑色、农产品、能化的停板幅度与交易限额不同。2015 年以后各所多次调整，历史必须用当时合约表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主数据按所–品种–合约。波动率曲面挂在对应期货价格上，delta 对冲用该期货，并计入夜盘跳空。季节虚拟变量或库存代理进入 RV 模型，避免把产季高峰当「alpha」。到期：期权到期与期货交割不同步时，基差与转换风险单列。与国债期货期权（若讨论）分开，那是利率市场。</p><p>跨市场：用商品期权对冲股票商品链公司，残差含基差、外汇与股票涨跌停。不要假设完美传递。</p><h3 id="波动率风险溢价的样本" tabindex="-1">波动率风险溢价的样本 <a class="header-anchor" href="#波动率风险溢价的样本" aria-label="Permalink to &quot;波动率风险溢价的样本&quot;">​</a></h3><p>中国商品期权上市偏晚，样本短，危机日少。VRP 估计的标准误大。应报告子样本与流动性过滤，而不是一个显著 t 值打天下。这与研究日志课的尝试次数约束一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>便利收益使近月期货可以高于远月，期权的远期波动与偏斜随之变。库存信息在现货与仓单上，不一定在股票分析师共识里。因此商品期权隐含对农产品与能化有独立信息，对「全 A 情绪」则噪声更大。保证金联立：期货与期权同一 CCP 池，压力日共同抽 VM。</p>',16)),(o(),p(h,null,{default:n(()=>[E(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20Fut%5B%22%E5%95%86%E5%93%81%E6%9C%9F%E8%B4%A7%20%E5%90%AB%E5%A4%9C%E7%9B%98%22%5D%20--%3E%20Opt%5B%22%E5%95%86%E5%93%81%E6%9C%9F%E6%9D%83%22%5D%0A%20%20Inv%5B%22%E5%BA%93%E5%AD%98%E4%B8%8E%E4%BA%A7%E5%AD%A3%22%5D%20--%3E%20RV%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20Opt%20--%3E%20IV%5B%22%E9%9A%90%E5%90%AB%E6%B3%A2%E5%8A%A8%E6%9B%B2%E9%9D%A2%22%5D%0A%20%20IV%20--%3E%20VRP%5B%22IV%20%E5%87%8F%20RV%20%E9%A1%BB%E5%88%86%E6%AE%B5%22%5D%0A%20%20RV%20--%3E%20VRP%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"不提供逼仓、交割月操纵或利用仓单信息违规交易的方法。原油等特定品种有额外监管。场外商品期权与场内不可混用保证金数字。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"商品期权的标的是期货，时钟含夜盘，季节性来自库存，不是股票 T+1。"),e("li",null,"VRP 必须按品种与合约月分段；样本短，勿过拟合。"),e("li",null,"容量看期权深度与期货对冲，不看现货市场规模。"),e("li",null,"出处：上期所、大商所、郑商所期权合约与规则。")],-1))])}const P=i(u,[["render",m]]);export{b as __pageData,P as default};
